async function waitForScreenshotReady(){for(;;){const n=await fetch("/api/screenshotready.json");if(!n.ok)throw new Error("Failed to check screenshot status.");const t=await n.json();if(t.ready)return;await new Promise(n=>setTimeout(n,100))}}async function screenshot(){try{await fetch("/api/takescreenshot");await waitForScreenshotReady();await fetch("/api/downloadscreenshot").then(n=>n.blob()).then(n=>{var i=window.URL.createObjectURL(n),t=document.createElement("a");t.href=i;t.download="screenshot.png";document.body.appendChild(t);t.click();t.remove()})}catch(n){content.innerHTML="Failed to connect."}}async function reboot(){await fetch("/api/reboot")}async function shutdown(){await fetch("/api/shutdown")}window.onload=function(){document.getElementById("year").textContent=(new Date).getFullYear()};